// Generates everything that derives from the two token sources
// (scripts/token-source.ts) and writes it, or with --check fails when a
// generated file is stale. Never edit the generated files by hand: after a
// change of brand/ or tokens/, and after a merge, run `bun run tokens`.
//
//   app/v1/kit/tokens.css   CSS custom properties, light and dark
//   app/v1/kit/tokens.ts    the same values for TypeScript
//   app/v1/kit/fonts.css    @font-face for the brand's fonts
//   app/v1/kit/fonts/       the brand's font files and their licences, copied
//   app/v1/kit/brand.ts     the brand's name, summary, logo and illustrations
//   app/v1/kit/manifest.json  SHA-256 of every file of the kit (the lock's anchor)
//   app/v1/public/favicon.svg  the viewer's favicon, from the logo
//   DESIGN.md               the design system for agents (DESIGN.md format)
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import packageJson from "../package.json";
import { designMd } from "./design-md";
import { type Brand, loadTokens, type Resolved, ROOT, THEMES, type Theme } from "./token-source";

const KIT = join(ROOT, "app/v1/kit");
const GENERATED =
  "Generated by app/v1/scripts/tokens.ts from brand/brand.json and tokens/tokens.json. Do not edit: change a source and run `bun run tokens`.";

type Output = { path: string; content: string | Uint8Array };

const quote = (family: string) =>
  /^[\w-]+$/.test(family) && !/\s/.test(family) ? family : `"${family}"`;
const stack = (brand: Brand, role: keyof Brand["fonts"]) => {
  const font = brand.fonts[role];
  return [font.family, ...font.fallback].map(quote).join(", ");
};

function themeBlock(tokens: Resolved, theme: Theme): string[] {
  const lines = [`  color-scheme: ${theme};`];
  for (const [role, source] of Object.entries(tokens.sources[theme])) {
    const value = /^#/.test(source) ? source : `var(--ds-palette-${source.replace(".", "-")})`;
    lines.push(`  --ds-color-${role}: ${value};`);
  }
  for (const [name, value] of Object.entries(tokens.system.shadow)) {
    lines.push(`  --ds-shadow-${name}: ${value[theme]};`);
  }
  return lines;
}

function tokensCss(tokens: Resolved): string {
  const { brand, system } = tokens;
  const root: string[] = [];
  for (const [ramp, steps] of Object.entries(brand.palette)) {
    for (const [step, value] of Object.entries(steps))
      root.push(`  --ds-palette-${ramp}-${step}: ${value};`);
  }
  for (const role of ["text", "heading", "mono"] as const)
    root.push(`  --ds-font-${role}: ${stack(brand, role)};`);
  for (const [name, role] of Object.entries(system.type)) {
    root.push(`  --ds-type-${name}-font: var(--ds-font-${role.font});`);
    root.push(`  --ds-type-${name}-size: ${role.size};`);
    root.push(`  --ds-type-${name}-leading: ${role.leading};`);
    root.push(`  --ds-type-${name}-weight: ${role.weight};`);
    root.push(`  --ds-type-${name}-tracking: ${role.tracking};`);
  }
  for (const [key, value] of Object.entries(system.space))
    root.push(`  --ds-space-${key}: ${value};`);
  for (const [key, value] of Object.entries(brand.radius))
    root.push(`  --ds-radius-${key}: ${value};`);
  for (const [key, value] of Object.entries(system.motion.duration))
    root.push(`  --ds-duration-${key}: ${value};`);
  for (const [key, value] of Object.entries(system.motion.ease))
    root.push(`  --ds-ease-${key}: ${value};`);
  for (const [key, value] of Object.entries(system.size))
    root.push(`  --ds-size-${key}: ${value};`);
  for (const [key, value] of Object.entries(system.z)) root.push(`  --ds-z-${key}: ${value};`);
  const breakpoints = Object.entries(system.breakpoint)
    .map(([key, value]) => `${key} ${value}`)
    .join(", ");
  return [
    `/* ${GENERATED} */`,
    "",
    `/* Breakpoints (CSS cannot read a custom property in a media query): ${breakpoints}. */`,
    ":root {",
    ...root,
    "}",
    "",
    "/* Light is the default theme; data-theme on any element switches it for that subtree. */",
    ':root,\n[data-theme="light"] {',
    ...themeBlock(tokens, "light"),
    "}",
    "",
    '[data-theme="dark"] {',
    ...themeBlock(tokens, "dark"),
    "}",
    "",
    "/* Without a choice the page follows the device. */",
    "@media (prefers-color-scheme: dark) {",
    '  :root:not([data-theme="light"]) {',
    ...themeBlock(tokens, "dark").map((line) => `  ${line}`),
    "  }",
    "}",
    "",
  ].join("\n");
}

const UNICODE = {
  latin:
    "U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD",
  "latin-ext":
    "U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF",
} as const;

function fonts(brand: Brand): Output[] {
  const faces: string[] = [`/* ${GENERATED} */`, ""];
  const outputs: Output[] = [];
  const files = new Set<string>();
  for (const role of ["text", "heading", "mono"] as const) {
    const font = brand.fonts[role];
    for (const { file, subset } of font.files) {
      const name = file.split("/").at(-1) ?? file;
      files.add(file);
      faces.push(
        "@font-face {",
        `  font-family: ${quote(font.family)};`,
        "  font-style: normal;",
        "  font-display: swap;",
        `  font-weight: ${font.weight};`,
        `  src: url("./fonts/${name}") format("woff2");`,
        `  unicode-range: ${UNICODE[subset]};`,
        "}",
        "",
      );
    }
  }
  outputs.push({ path: "app/v1/kit/fonts.css", content: faces.join("\n") });
  const fontDir = join(ROOT, "brand/fonts");
  for (const name of readdirSync(fontDir).sort()) {
    const path = `fonts/${name}`;
    if (!files.has(path) && !name.startsWith("LICENSE")) continue;
    outputs.push({ path: `app/v1/kit/fonts/${name}`, content: readFileSync(join(fontDir, name)) });
  }
  return outputs;
}

const literal = (value: unknown) => JSON.stringify(value, null, 2);

function tokensTs(tokens: Resolved): string {
  const { brand, system } = tokens;
  const font = Object.fromEntries(
    (["text", "heading", "mono"] as const).map((role) => [role, stack(brand, role)]),
  );
  const shadow = Object.fromEntries(
    THEMES.map((theme) => [
      theme,
      Object.fromEntries(Object.entries(system.shadow).map(([k, v]) => [k, v[theme]])),
    ]),
  );
  const use = Object.fromEntries(
    Object.entries(system.color).map(([role, value]) => [role, value.use]),
  );
  return [
    `// ${GENERATED}`,
    "",
    `export const palette = ${literal(brand.palette)} as const;`,
    "",
    "/** Every colour role, resolved, in both themes. */",
    `export const color = ${literal(tokens.colors)} as const;`,
    "",
    "/** Where each role comes from: a step of the palette or a literal colour. */",
    `export const colorSource = ${literal(tokens.sources)} as const;`,
    "",
    "/** What each colour role is for. */",
    `export const colorUse = ${literal(use)} as const;`,
    "",
    "/** The role pairs that must reach WCAG contrast: 4.5:1 for text, 3:1 for graphics. */",
    `export const contrastPairs = ${literal(system.contrast)} as const;`,
    "",
    `export const font = ${literal(font)} as const;`,
    "",
    `export const type = ${literal(system.type)} as const;`,
    "",
    `export const space = ${literal(system.space)} as const;`,
    "",
    `export const radius = ${literal(brand.radius)} as const;`,
    "",
    `export const shadow = ${literal(shadow)} as const;`,
    "",
    `export const motion = ${literal(system.motion)} as const;`,
    "",
    `export const size = ${literal(system.size)} as const;`,
    "",
    `export const z = ${literal(system.z)} as const;`,
    "",
    `export const breakpoint = ${literal(system.breakpoint)} as const;`,
    "",
    "export type Theme = keyof typeof color;",
    "export type ColorRole = keyof typeof color.light;",
    "export type TypeRole = keyof typeof type;",
    "export type SpaceStep = keyof typeof space;",
    "export type RadiusStep = keyof typeof radius;",
    "",
    '/** A token as a CSS custom property, for inline styles: `cssVar("color", "ink")`. */',
    "export function cssVar(",
    '  group: "color" | "space" | "radius" | "shadow" | "font" | "size" | "z" | "duration" | "ease",',
    "  name: string,",
    "): string {",
    // biome-ignore lint/suspicious/noTemplateCurlyInString: this is the generated source text
    "  return `var(--ds-${group}-${name})`;",
    "}",
    "",
  ].join("\n");
}

function svgParts(path: string): { viewBox: string; markup: string } {
  const svg = readFileSync(join(ROOT, "brand", path), "utf8").trim();
  const match = /^<svg\b([^>]*)>([\s\S]*)<\/svg>$/.exec(svg);
  const viewBox = match?.[1] ? /viewBox="([^"]+)"/.exec(match[1])?.[1] : undefined;
  if (!match || !viewBox) throw new Error(`brand/${path} is not one <svg> with a viewBox`);
  const attributes = (match[1] ?? "")
    .replace(/\s*xmlns="[^"]*"/, "")
    .replace(/\s*viewBox="[^"]*"/, "")
    .trim();
  const markup = (match[2] ?? "")
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
    .join("");
  return { viewBox, markup: attributes ? `<g ${attributes}>${markup}</g>` : markup };
}

function brandTs(brand: Brand): string {
  const illustrations = Object.fromEntries(
    Object.entries(brand.illustrations).map(([name, path]) => [name, svgParts(path)]),
  );
  return [
    `// ${GENERATED}`,
    "",
    "/** The name of the brand, as people write it. */",
    `export const brandName = ${JSON.stringify(brand.name)};`,
    "",
    `export const brandSummary = ${literal(brand.summary)} as const;`,
    "",
    "/** The design system's repository; the viewer links each page to its source there. */",
    `export const repository = ${JSON.stringify(brand.repository)};`,
    "",
    "/** The logo symbol (brand/logo): inline SVG markup that draws in currentColor. */",
    `export const logoSymbol = ${literal(svgParts(brand.logo.symbol))} as const;`,
    "",
    "/** The brand's own illustrations (brand/illustrations). */",
    `export const illustrations = ${literal(illustrations)} as const;`,
    "",
    "export type IllustrationName = keyof typeof illustrations;",
    "",
  ].join("\n");
}

/** The favicon from the logo symbol, in the ink and accent of both themes. */
function favicon(tokens: Resolved): string {
  const { viewBox, markup } = svgParts(tokens.brand.logo.symbol);
  const { light, dark } = tokens.colors;
  return [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${viewBox}">`,
    `<style>svg{color:${light.ink};--ds-color-accent:${light.accent}}@media (prefers-color-scheme:dark){svg{color:${dark.ink};--ds-color-accent:${dark.accent}}}</style>`,
    markup,
    "</svg>",
    "",
  ].join("\n");
}

function list(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const path = join(dir, entry.name);
    return entry.isDirectory() ? list(path) : [path];
  });
}

const sha256 = (content: string | Uint8Array) => createHash("sha256").update(content).digest("hex");

function manifest(outputs: Output[]): Output {
  const generated = new Map(outputs.map((output) => [output.path, output.content]));
  const files: Record<string, string> = {};
  const paths = new Set([
    ...list(KIT).map((path) => relative(ROOT, path).split("\\").join("/")),
    ...generated.keys(),
  ]);
  for (const path of [...paths].sort()) {
    if (!path.startsWith("app/v1/kit/") || path === "app/v1/kit/manifest.json") continue;
    const content = generated.get(path) ?? readFileSync(join(ROOT, path));
    files[path.slice("app/v1/kit/".length)] = sha256(content);
  }
  return {
    path: "app/v1/kit/manifest.json",
    content: `${JSON.stringify({ schema: "design-system.kit-manifest.v1", version: packageJson.version, files }, null, 2)}\n`,
  };
}

export function generate(): Output[] {
  const tokens = loadTokens();
  const outputs: Output[] = [
    { path: "app/v1/kit/tokens.css", content: tokensCss(tokens) },
    { path: "app/v1/kit/tokens.ts", content: tokensTs(tokens) },
    { path: "app/v1/kit/brand.ts", content: brandTs(tokens.brand) },
    { path: "app/v1/public/favicon.svg", content: favicon(tokens) },
    ...fonts(tokens.brand),
  ];
  outputs.push({ path: "DESIGN.md", content: designMd(tokens) });
  outputs.push(manifest(outputs));
  return outputs;
}

function same(path: string, content: string | Uint8Array): boolean {
  const full = join(ROOT, path);
  if (!existsSync(full)) return false;
  const current = readFileSync(full);
  return Buffer.compare(current, Buffer.from(content)) === 0;
}

/** Generated files that differ from what the sources give, and font copies no source names. */
export function stale(): string[] {
  const outputs = generate();
  const expected = new Set(outputs.map((output) => output.path));
  const extra = list(join(KIT, "fonts"))
    .map((path) => relative(ROOT, path).split("\\").join("/"))
    .filter((path) => !expected.has(path));
  return [
    ...outputs.filter((output) => !same(output.path, output.content)).map((o) => o.path),
    ...extra,
  ];
}

if (import.meta.main) {
  if (process.argv.includes("--check")) {
    const paths = stale();
    if (paths.length > 0) {
      console.error(`stale generated files, run \`bun run tokens\`:\n  ${paths.join("\n  ")}`);
      process.exit(1);
    }
    console.log("generated files are up to date");
  } else {
    rmSync(join(KIT, "fonts"), { recursive: true, force: true });
    for (const output of generate()) {
      mkdirSync(dirname(join(ROOT, output.path)), { recursive: true });
      writeFileSync(join(ROOT, output.path), output.content);
    }
    // The manifest hashes the kit as it is now on disk, so write it once more.
    const last = generate().at(-1);
    if (last) writeFileSync(join(ROOT, last.path), last.content);
    console.log("wrote the generated files");
  }
}
